test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', name: 'Printed flyer', qty: 1, unitPrice: 5000, vatRate: 9, discountPercent: 0 },
      { sku: 'TALK', name: 'Conference talk', qty: 1, unitPrice: 2000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17000);
  // VAT: 10000*0.21 + 5000*0.09 + 2000*0 = 2100 + 450 = 2550
  assert.equal(totals.vat, 2550);
  assert.equal(totals.total, 19550);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 10 * 1000 = 10000
  // Discount: 10000 * 0.1 = 1000
  // After discount: 10000 - 1000 = 9000
  // VAT: 9000 * 0.21 = 1890
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 1890);
  assert.equal(totals.total, 10890);
});

test('invoiceTotals with fractional VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'PRINT-A4', name: 'Printed flyer', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 100 * 37 = 3700
  // VAT: 3700 * 0.09 = 333, should be exactly 333 (no fraction)
  assert.equal(totals.subtotal, 3700);
  assert.equal(totals.vat, 333);
  assert.equal(totals.total, 4033);
});

